<?php

namespace App\Services\Reports;

use Illuminate\Support\Str;

/**
 * Minimal, safe placeholder engine for admin-editable email templates.
 *
 *   {{ key }}                          scalar value (HTML-escaped)
 *   {{ something_table }}              pre-rendered HTML table (inserted raw — generated by OMS)
 *   {{#each list}} ... {{/each}}       loop; item keys are available inside
 *   {{#for each active network outage}} ... {{/for}}   spec §15 syntax (aliases below)
 *   **text**                           bold (within one line; may wrap placeholders, e.g. **{{ticket}}**)
 *
 * Template text itself is always escaped, so an edited template can never inject markup. Bold is
 * applied with private marker characters that are stripped from every value, so data can't fake it.
 */
class TemplateRenderer
{
    private const BOLD_OPEN = "\x02";

    private const BOLD_CLOSE = "\x03";

    public const LOOP_ALIASES = [
        'active network outage' => 'network_outages',
        'network outage' => 'network_outages',
        'ftth outage' => 'ftth_outages',
        '4g outage' => 'mobility_outages',
        'mobility outage' => 'mobility_outages',
        'core outage' => 'core_outages',
        'system outage' => 'system_outages',
        'major incident' => 'major_incidents',
        'critical incident' => 'major_incidents',
        'closed outage' => 'closed_outages',
        'resolved outage' => 'closed_outages',
    ];

    public function render(string $template, array $data): string
    {
        $template = str_replace([self::BOLD_OPEN, self::BOLD_CLOSE], '', $this->normalise($template));

        // **text** → markers (only on one line, so a stray "**" can never bold the rest of the e-mail).
        $template = (string) preg_replace('/\*\*(?=\S)([^\r\n]*?\S)\*\*/', self::BOLD_OPEN.'$1'.self::BOLD_CLOSE, $template);

        $html = nl2br($this->renderBlock($template, $data), false);

        return str_replace([self::BOLD_OPEN, self::BOLD_CLOSE], ['<strong>', '</strong>'], $html);
    }

    /** Plain-text rendering for subjects (no HTML, no loops, bold markers dropped). */
    public function renderText(string $template, array $data): string
    {
        $template = (string) preg_replace('/\*\*(?=\S)([^\r\n]*?\S)\*\*/', '$1', $template);

        return (string) preg_replace_callback('/\{\{\s*([a-z0-9_]+)\s*\}\}/i', function (array $m) use ($data): string {
            $value = $data[$m[1]] ?? '';

            return is_scalar($value) ? (string) $value : '';
        }, $template);
    }

    /** @return list<string> */
    public static function placeholders(): array
    {
        return [
            'report_time', 'report_date', 'period_start', 'period_end', 'active_outages', 'new_outages', 'resolved_outages',
            'critical_outages', 'customers_affected', 'sla_compliant', 'sla_at_risk', 'sla_breached', 'sms_sent', 'sms_pending',
            'credits_shared', 'credits_pending', 'oldest_active', 'sites_down', 'cells_down', 'power_faults', 'other_4g',
            'core_summary_or_no_core_outages', 'system_summary_or_no_system_outages', 'major_incidents_text', 'closed_summary',
            'summary_table', 'trend_table', 'top_olts_table', 'top_services_table', 'active_table',
        ];
    }

    private function normalise(string $template): string
    {
        $template = (string) preg_replace_callback('/\{\{#for each ([^}]+)\}\}/i', function (array $m): string {
            $phrase = Str::of($m[1])->lower()->squish()->toString();
            $key = self::LOOP_ALIASES[$phrase] ?? self::LOOP_ALIASES[Str::singular($phrase)] ?? Str::snake(Str::plural($phrase));

            return '{{#each '.$key.'}}';
        }, $template);

        return (string) preg_replace('/\{\{\/for\}\}/i', '{{/each}}', $template);
    }

    private function renderBlock(string $template, array $data): string
    {
        $raw = [];

        $template = (string) preg_replace_callback('/\{\{#each\s+([a-z0-9_]+)\s*\}\}(.*?)\{\{\/each\}\}/is', function (array $m) use ($data, &$raw): string {
            $items = $data[$m[1]] ?? [];
            $out = '';

            foreach (is_iterable($items) ? $items : [] as $item) {
                $out .= $this->renderBlock(ltrim($m[2], "\r\n"), array_merge($data, (array) $item));
            }

            if ($out === '') {
                $out = e('None.')."\n";
            }

            $token = '@@RAW'.count($raw).'@@';
            $raw[$token] = $out;

            return $token;
        }, $template);

        $parts = preg_split('/(\{\{\s*[a-z0-9_]+\s*\}\}|@@RAW\d+@@)/i', $template, -1, PREG_SPLIT_DELIM_CAPTURE) ?: [];
        $html = '';

        foreach ($parts as $part) {
            if (isset($raw[$part])) {
                $html .= $raw[$part];
            } elseif (preg_match('/^\{\{\s*([a-z0-9_]+)\s*\}\}$/i', $part, $m)) {
                $value = $data[$m[1]] ?? '';
                $value = str_ends_with($m[1], '_table') ? (string) $value : e(is_scalar($value) ? (string) $value : '');
                // Data can never open or close bold itself.
                $html .= str_replace([self::BOLD_OPEN, self::BOLD_CLOSE], '', $value);
            } else {
                $html .= e($part);
            }
        }

        return $html;
    }
}
